/*setBntTrxlUploadList*/
INSERT INTO BNTTRXL ( DOC_NAME , TARGET , KEY_1 , KEY_2 , KEY_3 , KEY_4 , KEY_5 , KEY_6 , KEY_7 , KEY_8 , KEY_9 , KEY_10 , KEY_11 , KEY_12 , KEY_13 , KEY_14 , KEY_15 , KEY_16 , KEY_17 , KEY_18 , KEY_19 , KEY_20 , KEY_21 , KEY_22 , KEY_23 , KEY_24 , KEY_25 , KEY_26 , KEY_27 , KEY_28 , KEY_29 , KEY_30 , KEY_31 , KEY_32 , KEY_33 , KEY_34 , KEY_35 , KEY_38 , KEY_39 , KEY_40 ) VALUES( #{DOC_NAME}, --DOC_NAME (SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = #{BUYER} AND STATUS IN ('C','R')), --[01] TARGET BYCA_COMORG_CODE #{BUYER_ITEM_NO}, --[02] KEY_1 BUYER_ITEM_NO NVL((SELECT AGENT FROM ICOMCQDT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = #{BUYER} AND STATUS IN ('C','R')) AND CONTRACT_NO=#{CONTRACT_NO} AND CONTRACT_SEQ=#{CONTRACT_SEQ}),' '), --[03] KEY_2 AGENT_CODE #{CONTRACT_NO}, --[04] KEY_3 CONTRACT_NO #{CONTRACT_SEQ}, --[05] KEY_4 CONTRACT_SEQ #{STATUS_TEXT}, --[06] KEY_5 STATUS_TEXT #{BUYER}, --[07] KEY_6 ST_BUYER #{ST_USER_ID}, --[08] KEY_7 reg_user_id #{TRXL_GUBUN}, --[09] KEY_8 trxl_gubun (SELECT TO_NUMBER(NVL(MAX(TO_NUMBER(KEY_9)),0))+1 FROM BNTTRXL WHERE DOC_NAME = #{DOC_NAME} ), #{LIST_PRICE}, -- LIST_PRICE KEY_10 변경전 매입단가
#{UNIT_PRICE}, --UNIT_PRICE KEY_11 변경전 매출단가 DECODE(#{AFTER_AGENT},'',NVL((SELECT AGENT FROM ICOMCQDT WHERE BUYER=(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = #{BUYER} AND STATUS IN ('C','R')) AND CONTRACT_NO=#{CONTRACT_NO} AND CONTRACT_SEQ=#{CONTRACT_SEQ}),' '),#{AFTER_AGENT}), --AFTER_AGENT KEY_12 변경후 협력사 #{AFTER_LIST_PRICE}, --AFTER_LIST_PRICE KEY_13 변경후 매입단가 #{AFTER_UNIT_PRICE}, --KEY_14 AFTER_UNIT_PRICE 변경후 매출단가 #{CH_PROCESS_TYPE}, --KEY_15 --KEY_15 CH_PROCESS_TYPE 변경 후 거래유형 #{CH_WAREHOUSE_CODE}, --KEY_16 CH_WAREHOUSE_CODE 변경 후 물류센터코드 #{AFTER_ITEM_MAKE_TYPE}, #{DELIVERY_LT}, #{AFTER_DELIVERY_LT}, #{CH_SELL_CLOSE_DATE}, #{CH_MIN_ORDER_QTY}, #{CH_PUR_UNIT_QTY}, #{CH_SELLER_AREA}, #{CH_BUY_CLOSE_DATE}, #{UNIT_PRICE_CHANGE_REASON}, -- KEY_27 #{LIST_PRICE_CHANGE_REASON}, -- KEY_28 #{CUSTOMIZATION_YN}, -- KEY_29 #{DIRECT_SOURCING_YN}, -- KEY_30 #{COMMISSION_PERCENTAGE}, -- KEY_31 #{MARKET_PRICE}, -- KEY_32 #{MARKET_SHIPPING_FEE}, -- KEY_33 #{MARKET_PRICE_TOTAL}, -- KEY_34 #{MARKET_SAVING_RATE}, -- KEY_35 #{MARKET_URL}, -- KEY_36 #{MARKET_COMMNET}, -- KEY_37 #{QUOTATION_NO}, -- KEY_38 #{QUOTATION_SEQ}, -- KEY_39 'N' -- KEY_40
)

/*saveMasterMpIfSamsungCatalogUploadList*/ UPDATE BNTTRXL SET KEY_12 = #{AFTER_AGENT}, KEY_13 = #{AFTER_LIST_PRICE}, KEY_14 = #{AFTER_UNIT_PRICE}, KEY_17 = #{AFTER_ITEM_MAKE_TYPE}, KEY_19 = #{AFTER_DELIVERY_LT}, KEY_20 = #{CH_SELL_CLOSE_DATE}, KEY_24 = #{CH_BUY_CLOSE_DATE}, KEY_21 = #{CH_MIN_ORDER_QTY}, KEY_22 = #{CH_PUR_UNIT_QTY}, KEY_23 = #{CH_SELLER_AREA}, KEY_15 = #{CH_PROCESS_TYPE}, KEY_25 = #{UNIT_PRICE_CHANGE_REASON}, KEY_26 = #{LIST_PRICE_CHANGE_REASON}, KEY_16 = #{CH_WAREHOUSE_CODE}, KEY_36 = #{IMAGE_KEY}, KEY_37 = #{IMAGE_KEY2}, KEY_38 = #{QUOTATION_NO}, KEY_39 = #{QUOTATION_SEQ}
WHERE DOC_NAME = #{DOC_NAME} --[01] DOC_NAME AND TARGET = #{TARGET} --[02] BYCA_COMORG_CODE
AND KEY_1 = #{BUYER_ITEM_NO} -- BUYER_ITEM_NO
AND KEY_6 = #{KEY_6} --[03] BUYER AND KEY_7 = #{KEY_7} --[04] ST_USER_ID AND KEY_8 = #{KEY_8} --[05] TRXL_GUBUN AND KEY_9 = #{KEY_9} --[06] KEY_9

