UPDATE SEC_ITEM_UPLOAD SET CUSTOMIZATION_YN = #{CUSTOMIZATION_YN}, DIRECT_SOURCING_YN = #{DIRECT_SOURCING_YN}, COMMISSION_PERCENTAGE = #{COMMISSION_PERCENTAGE}, MARKET_PRICE = #{MARKET_PRICE}, MARKET_SHIPPING_FEE = #{MARKET_SHIPPING_FEE}, MARKET_PRICE_TOTAL = #{MARKET_PRICE_TOTAL}, MARKET_SAVING_RATE = #{MARKET_SAVING_RATE}, MARKET_URL = #{MARKET_URL}, MARKET_COMMNET = #{MARKET_COMMNET}, KEP_IMAGE_KEY = #{IMAGE_KEY}, AGENT_IMAGE_KEY = #{IMAGE_KEY2}, MARKET_DOC_TYPE = DECODE(#{IMAGE_KEY2}, '','A','B')
